-- Täydennetään MHU Kokkola 2024 urakalle sopivat tiedot välikatselmusta varten
DO $$
    DECLARE
        urakkaid                INTEGER;
        kayttajaid              INTEGER;
        tavoitehinta_           DECIMAL(10, 2)     := 1988273.5;
        kattohinta_             DECIMAL(10, 2)     := 2385928.2;
        sopimusid               INTEGER;
        toimenpideinstanssi1    INTEGER;
        toimenpideinstanssi2    INTEGER;
        toimenpideinstanssi3    INTEGER;
        toimenpideinstanssi4    INTEGER;
        toimenpideinstanssi5    INTEGER;
        toimenpideinstanssi6    INTEGER;
        toimenpideinstanssi7    INTEGER;
        vahvistettavat_osiot    SUUNNITTELU_OSIO[] := ARRAY ['hankintakustannukset', 'erillishankinnat', 'johto-ja-hallintokorvaus', 'hoidonjohtopalkkio', 'tavoite-ja-kattohinta', 'tavoitehintaiset-rahavaraukset'];
        osio_                   SUUNNITTELU_OSIO;
        toimenkuva_vtyonjohtaja INTEGER;

    BEGIN
        -- Hae kokkolan id
        SELECT id INTO urakkaid FROM urakka WHERE nimi = 'EPO MHU Kokkola 2024-2029, P';
        select id into sopimusid from sopimus where urakka = urakkaid;
        -- Hae käyttäjän id
        SELECT id INTO kayttajaid FROM kayttaja WHERE kayttajanimi = 'jvh';

        select id into toimenpideinstanssi1 FROM toimenpideinstanssi where nimi = 'EPO MHU Kokkola 2024-2029, P Talvihoito TP';
        select id into toimenpideinstanssi2 FROM toimenpideinstanssi where nimi = 'EPO MHU Kokkola 2024-2029, P Liikenneympäristön hoito TP';
        select id into toimenpideinstanssi3 FROM toimenpideinstanssi where nimi = 'EPO MHU Kokkola 2024-2029, P Soratien hoito TP';
        select id into toimenpideinstanssi4 FROM toimenpideinstanssi where nimi = 'EPO MHU Kokkola 2024-2029, P Päällystepaikkaukset TP';
        select id into toimenpideinstanssi5 FROM toimenpideinstanssi where nimi = 'EPO MHU Kokkola 2024-2029, P MHU Ylläpito TP';
        select id into toimenpideinstanssi6 FROM toimenpideinstanssi where nimi = 'EPO MHU Kokkola 2024-2029, P MHU Korvausinvestointi TP';
        select id into toimenpideinstanssi7 FROM toimenpideinstanssi where nimi = 'EPO MHU Kokkola 2024-2029, P MHU ja HJU Hoidon johto';

        select id into toimenkuva_vtyonjohtaja from johto_ja_hallintokorvaus_toimenkuva where toimenkuva = 'vastuunalainen työnjohtaja' AND "urakka-id" is null;

    
        -- Kiinteähintaiset työt

        
        -- Kustannusarvioitu tyo



        -- Vahvistetaan 2024 vuoden kustannussuunnitelma

        FOREACH osio_ in ARRAY vahvistettavat_osiot
            LOOP
                VALUES (urakkaid, osio_, 1, true, kayttajaid, NOW(), kayttajaid, NOW())
                ON CONFLICT DO NOTHING;
            END LOOP;

    END
$$ LANGUAGE plpgsql;
